-- LIBRERIA LA CRAYOLA GIGANTE - Sprint 1 (Oracle Database 19c+)
-- Ejecutar conectado con el usuario/esquema de la aplicacion, NO con SYS/SYSTEM.
-- Las tablas usan GENERATED BY DEFAULT AS IDENTITY; Oracle conserva DATE con hora.

CREATE TABLE roles (
 id_rol NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 nombre VARCHAR2(50 CHAR) NOT NULL UNIQUE,
 descripcion VARCHAR2(250 CHAR),
 estado CHAR(1) DEFAULT 'A' NOT NULL CHECK (estado IN ('A','I'))
);
CREATE TABLE permisos (
 id_permiso NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 codigo VARCHAR2(80 CHAR) NOT NULL UNIQUE,
 descripcion VARCHAR2(250 CHAR) NOT NULL
);
CREATE TABLE rol_permiso (
 id_rol NUMBER NOT NULL,
 id_permiso NUMBER NOT NULL,
 CONSTRAINT pk_rol_permiso PRIMARY KEY (id_rol,id_permiso),
 CONSTRAINT fk_rp_rol FOREIGN KEY (id_rol) REFERENCES roles(id_rol),
 CONSTRAINT fk_rp_permiso FOREIGN KEY (id_permiso) REFERENCES permisos(id_permiso)
);
CREATE TABLE usuarios (
 id_usuario NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 nombre_completo VARCHAR2(120 CHAR) NOT NULL,
 nombre_usuario VARCHAR2(50 CHAR) NOT NULL UNIQUE,
 contrasena_hash VARCHAR2(255 CHAR) NOT NULL,
 id_rol NUMBER NOT NULL,
 estado CHAR(1) DEFAULT 'A' NOT NULL CHECK (estado IN ('A','I')),
 creado_en TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
 CONSTRAINT fk_usuario_rol FOREIGN KEY (id_rol) REFERENCES roles(id_rol)
);
CREATE TABLE clientes (
 id_cliente NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 nombres VARCHAR2(100 CHAR) NOT NULL,
 apellidos VARCHAR2(100 CHAR),
 nit VARCHAR2(20 CHAR) UNIQUE,
 telefono VARCHAR2(25 CHAR),
 correo VARCHAR2(120 CHAR),
 direccion VARCHAR2(250 CHAR),
 estado CHAR(1) DEFAULT 'A' NOT NULL CHECK (estado IN ('A','I')),
 creado_en TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);
CREATE TABLE categorias (
 id_categoria NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 nombre VARCHAR2(100 CHAR) NOT NULL UNIQUE,
 descripcion VARCHAR2(250 CHAR),
 estado CHAR(1) DEFAULT 'A' NOT NULL CHECK (estado IN ('A','I'))
);
CREATE TABLE productos (
 id_producto NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 codigo VARCHAR2(50 CHAR) NOT NULL UNIQUE,
 nombre VARCHAR2(150 CHAR) NOT NULL,
 descripcion VARCHAR2(500 CHAR),
 precio NUMBER(12,2) NOT NULL CHECK (precio >= 0),
 stock NUMBER(10) DEFAULT 0 NOT NULL CHECK (stock >= 0),
 id_categoria NUMBER NOT NULL,
 estado CHAR(1) DEFAULT 'A' NOT NULL CHECK (estado IN ('A','I')),
 creado_en TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
 CONSTRAINT fk_producto_categoria FOREIGN KEY (id_categoria) REFERENCES categorias(id_categoria)
);
CREATE TABLE bitacora (
 id_bitacora NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 id_usuario NUMBER,
 accion VARCHAR2(80 CHAR) NOT NULL,
 tabla_afectada VARCHAR2(50 CHAR) NOT NULL,
 id_registro_afectado NUMBER,
 detalle VARCHAR2(1000 CHAR),
 fecha_hora TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
 CONSTRAINT fk_bitacora_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios(id_usuario)
);
CREATE INDEX ix_usuarios_rol ON usuarios(id_rol);
CREATE INDEX ix_rp_permiso ON rol_permiso(id_permiso);
CREATE INDEX ix_productos_categoria ON productos(id_categoria);
CREATE INDEX ix_bitacora_usuario_fecha ON bitacora(id_usuario,fecha_hora);
CREATE INDEX ix_bitacora_fecha ON bitacora(fecha_hora);

